head.b:skin:
/* Race4thePrize NBA DFS Database - Blogger theme (light, mobile-first) */
:root{
  --bg:#ffffff; --ink:#15171c; --muted:#5d6370; --line:#e3e6eb; --soft:#f5f6f8;
  --accent:#e4572e; --accent-soft:#fdeee9; --navy:#1d3557; --good:#1f7a4d; --bad:#b4232c;
  --head:'Barlow Condensed', 'Arial Narrow', Arial, sans-serif;
  --body:'Source Sans 3', -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;text-size-adjust:100%}
body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.5 var(--body);overflow-x:hidden}
a{color:var(--navy)}
img{max-width:100%;height:auto}
.wrap{max-width:1100px;margin:0 auto;padding:0 16px}
/* Header */
.top{border-bottom:4px solid var(--accent);background:var(--bg)}
.top .wrap{padding-top:18px;padding-bottom:14px}
.kicker{font:700 13px/1 var(--head);letter-spacing:.12em;text-transform:uppercase;color:var(--accent)}
.title{font:800 clamp(30px,7vw,48px)/1.02 var(--head);margin:6px 0 6px;text-transform:uppercase;letter-spacing:.01em;color:var(--navy)}
.sub{color:var(--muted);font-size:14px;margin:0}
/* Tabs */
.tabs{position:sticky;top:0;z-index:5;background:var(--bg);border-bottom:1px solid var(--line)}
.tabs .wrap{display:flex;gap:6px;overflow-x:auto;-webkit-overflow-scrolling:touch;scrollbar-width:none;padding-top:10px;padding-bottom:10px}
.tabs .wrap::-webkit-scrollbar{display:none}
.tab{flex:0 0 auto;border:1px solid var(--line);background:var(--soft);color:var(--ink);font:700 15px/1 var(--head);letter-spacing:.06em;text-transform:uppercase;padding:10px 14px;border-radius:999px;cursor:pointer}
.tab.on{background:var(--navy);border-color:var(--navy);color:#fff}
.tab:focus-visible,.btn:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
/* Layout */
main.wrap{padding-top:18px;padding-bottom:40px}
.view[hidden]{display:none}
.toolbar{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 14px}
.toolbar input,.toolbar select{font:inherit;font-size:16px;padding:10px 12px;border:1px solid var(--line);border-radius:8px;background:#fff;color:var(--ink);min-width:0}
.toolbar input{flex:1 1 220px}
.toolbar select{flex:0 1 220px}
.btn{font:700 15px/1 var(--head);letter-spacing:.06em;text-transform:uppercase;padding:11px 14px;border:2px solid var(--navy);color:var(--navy);background:#fff;border-radius:8px;cursor:pointer;text-decoration:none;display:inline-block}
.btn.solid{background:var(--accent);border-color:var(--accent);color:#fff}
.msg{color:var(--muted);font-size:14px;min-height:20px;margin:-6px 0 10px}
.count{color:var(--muted);font-size:14px;margin:0 0 10px}
/* Quick hits */
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr));gap:16px}
.panel{border:1px solid var(--line);border-radius:12px;padding:14px 16px;background:#fff;min-width:0}
.panel h2{font:800 22px/1.1 var(--head);text-transform:uppercase;letter-spacing:.03em;margin:0 0 4px;color:var(--navy)}
.panel .hint{color:var(--muted);font-size:14px;margin:0 0 10px}
.panel.up h2{color:var(--good)} .panel.down h2{color:var(--bad)} .panel.sits h2{color:var(--accent)}
.hit{padding:10px 0;border-top:1px solid var(--line)}
.hit:first-of-type{border-top:none}
.hit .who{font-weight:700}
.hit .tm{display:inline-block;font:700 12px/1 var(--head);letter-spacing:.08em;background:var(--soft);border:1px solid var(--line);border-radius:4px;padding:3px 5px;margin-left:6px;vertical-align:2px;color:var(--muted)}
.hit .arrow{color:var(--accent);font-weight:700}
.hit p{margin:2px 0 0;font-size:15px;overflow-wrap:anywhere}
.src{font-size:12px;color:var(--muted)}
.src a{color:var(--muted)}
/* Cards */
.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,300px),1fr));gap:12px}
.card{border:1px solid var(--line);border-radius:12px;padding:12px 14px;background:#fff;min-width:0}
.card h3{font:800 20px/1.1 var(--head);text-transform:uppercase;margin:0 0 6px;color:var(--navy);overflow-wrap:anywhere}
.card .row{font-size:15px;margin:4px 0;overflow-wrap:anywhere}
.card .lbl{font:700 12px/1 var(--head);letter-spacing:.08em;text-transform:uppercase;color:var(--muted);display:block;margin-top:8px}
.pill{display:inline-block;font:700 12px/1 var(--head);letter-spacing:.06em;text-transform:uppercase;border-radius:999px;padding:4px 8px;margin:2px 4px 2px 0;background:var(--soft);border:1px solid var(--line);color:var(--ink)}
.pill.hurt{background:#fbe9ea;border-color:#f2c4c7;color:var(--bad)}
.pill.start{background:#e8f4ee;border-color:#c3e3d1;color:var(--good)}
.loading{color:var(--muted);padding:20px 0}
footer{border-top:1px solid var(--line);color:var(--muted);font-size:13px}
footer .wrap{padding-top:14px;padding-bottom:24px}
/* Blogger posts area (shown only off the homepage) */
.home .blog-area{display:none}
.blog-area{max-width:760px;margin:0 auto;padding:16px}
.blog-area .post-title{font:800 28px/1.1 var(--head);color:var(--navy)}
@media (max-width:600px){
  body{font-size:15px}
  .panel{padding:12px}
  .toolbar .btn{flex:1 1 auto;text-align:center}
}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}

body.script:
//
(function(){
  var SOURCES = [
    'https://cdn.jsdelivr.net/gh/nascardataguy2/nba-2026-27@main/data/db.json',
    'https://nascardataguy2.github.io/nba-2026-27/data/db.json'
  ];
  var AI_URLS = [
    'https://cdn.jsdelivr.net/gh/nascardataguy2/nba-2026-27@main/ai.txt',
    'https://nascardataguy2.github.io/nba-2026-27/ai.txt'
  ];
  var NAMES = {ATL:'Atlanta Hawks',BOS:'Boston Celtics',BKN:'Brooklyn Nets',CHA:'Charlotte Hornets',CHI:'Chicago Bulls',CLE:'Cleveland Cavaliers',DAL:'Dallas Mavericks',DEN:'Denver Nuggets',DET:'Detroit Pistons',GSW:'Golden State Warriors',HOU:'Houston Rockets',IND:'Indiana Pacers',LAC:'LA Clippers',LAL:'Los Angeles Lakers',MEM:'Memphis Grizzlies',MIA:'Miami Heat',MIL:'Milwaukee Bucks',MIN:'Minnesota Timberwolves',NOP:'New Orleans Pelicans',NYK:'New York Knicks',OKC:'Oklahoma City Thunder',ORL:'Orlando Magic',PHI:'Philadelphia 76ers',PHX:'Phoenix Suns',POR:'Portland Trail Blazers',SAC:'Sacramento Kings',SAS:'San Antonio Spurs',TOR:'Toronto Raptors',UTA:'Utah Jazz',WAS:'Washington Wizards'};
  var db = null, srcById = {};
  function $(id){ return document.getElementById(id); }
  function esc(s){ return String(s == null ? '' : s).replace(/[&<>"]/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); }
  function srcLink(id){
    var s = srcById[id];
    if (!s) return '';
    return '<div class="src">From: <a href="' + esc(s.url) + '" rel="noopener" target="_blank">' + esc(s.show) + ', ' + esc(s.date) + '</a></div>';
  }
  function tm(code){ return code ? '<span class="tm">' + esc(code) + '</span>' : ''; }

  function fetchFirst(urls, asText){
    var i = 0;
    function next(){
      if (i >= urls.length) return Promise.reject(new Error('all sources failed'));
      var u = urls[i++] + (urls[i-1].indexOf('github.io') > -1 ? ('?t=' + Date.now()) : '');
      return fetch(u, {cache:'no-store'}).then(function(r){
        if (!r.ok) throw new Error('bad status');
        return asText ? r.text() : r.json();
      }).catch(next);
    }
    return next();
  }

  function quick(){
    var q = db.quickhits || {};
    function panel(cls, title, hint, items, fn){
      if (!items || !items.length) return '';
      return '<div class="panel ' + cls + '"><h2>' + title + '</h2><p class="hint">' + hint + '</p>' + items.map(fn).join('') + '</div>';
    }
    function simple(it){ return '<div class="hit"><span class="who">' + esc(it.player) + '</span>' + tm(it.team) + '<p>' + esc(it.text) + '</p>' + srcLink(it.source) + '</div>'; }
    var html = '<div class="grid">' +
      panel('sits', 'If He Sits, Who Benefits', 'Check this when late injury news drops before lock.', q.if_sits, function(it){
        return '<div class="hit"><span class="who">' + esc(it.out) + '</span>' + tm(it.team) + ' <span class="arrow">\u2192</span> <span class="who">' + esc(it.benefits) + '</span><p>' + esc(it.text) + '</p>' + srcLink(it.source) + '</div>';
      }) +
      panel('up', 'Role Up', 'New team or bigger job. Early-season prices often lag behind these changes.', q.role_up, simple) +
      panel('down', 'Role Down', 'Last season\u2019s numbers probably will not repeat.', q.role_down, simple) +
      panel('rest', 'Rest Watch', 'Players likely to sit back-to-backs or get rest days early.', q.rest_watch, simple) +
      panel('out', 'Out to Start the Season', 'Known injuries as of the latest episodes.', q.out_to_start, simple) +
      '</div>';
    $('v-quick').innerHTML = html;
  }

  function teamOptions(sel){
    var codes = {};
    db.teams.forEach(function(t){ if (t.team) codes[t.team] = 1; });
    db.players.forEach(function(p){ if (p.team) codes[p.team] = 1; });
    Object.keys(codes).sort().forEach(function(c){
      var o = document.createElement('option'); o.value = c; o.textContent = c + ' \u2013 ' + (NAMES[c] || c); sel.appendChild(o);
    });
  }

  function teams(){
    var t = $('r4p-team').value;
    var list = db.teams.slice().sort(function(a,b){ return a.team < b.team ? -1 : 1; }).filter(function(x){ return !t || x.team === t; });
    $('r4p-teamcards').innerHTML = list.map(function(x){
      return '<div class="card"><h3>' + esc(NAMES[x.team] || x.team) + '</h3>' +
        '<span class="lbl">Projected starters</span><div class="row">' + esc(x.starters) + '</div>' +
        (x.bench ? '<span class="lbl">Bench order</span><div class="row">' + esc(x.bench) + '</div>' : '') +
        (x.backup_c ? '<span class="lbl">Backup center</span><div class="row">' + esc(x.backup_c) + '</div>' : '') +
        (x.coach ? '<span class="lbl">Coach</span><div class="row">' + esc(x.coach) + '</div>' : '') +
        '<span class="lbl">Notes</span><div class="row">' + esc(x.notes) + '</div>' + srcLink(x.source) + '</div>';
    }).join('') || '<p class="sub">No team preview has been processed for this team yet.</p>';
  }

  function playerCard(p){
    var pills = '';
    if (/starter/i.test(p.role)) pills += '<span class="pill start">' + esc(p.role) + '</span>';
    else if (p.role) pills += '<span class="pill">' + esc(p.role) + '</span>';
    if (p.status && !/^healthy$/i.test(p.status)) pills += '<span class="pill hurt">Health note</span>';
    return '<div class="card"><h3>' + esc(p.player) + ' ' + tm(p.team) + '</h3>' + pills +
      (p.minutes ? '<span class="lbl">Minutes</span><div class="row">' + esc(p.minutes) + '</div>' : '') +
      (p.usage ? '<span class="lbl">Usage</span><div class="row">' + esc(p.usage) + '</div>' : '') +
      (p.status ? '<span class="lbl">Health</span><div class="row">' + esc(p.status) + '</div>' : '') +
      (p.note ? '<span class="lbl">Note</span><div class="row">' + esc(p.note) + '</div>' : '') + srcLink(p.source) + '</div>';
  }

  function players(){
    var q = $('r4p-q').value.trim().toLowerCase(), t = $('r4p-pteam').value;
    var list = db.players.filter(function(p){
      if (t && p.team !== t) return false;
      if (!q) return true;
      return (p.player + ' ' + p.team + ' ' + (NAMES[p.team] || '') + ' ' + p.role + ' ' + p.minutes + ' ' + p.usage + ' ' + p.status + ' ' + p.note).toLowerCase().indexOf(q) > -1;
    }).sort(function(a,b){ return (a.team + a.player) < (b.team + b.player) ? -1 : 1; });
    $('r4p-count').textContent = list.length + ' of ' + db.players.length + ' players';
    $('r4p-playercards').innerHTML = list.map(playerCard).join('');
  }

  function injuries(){
    $('r4p-injcards').innerHTML = db.injuries.slice().sort(function(a,b){ return a.team < b.team ? -1 : 1; }).map(function(p){
      return '<div class="card"><h3>' + esc(p.player) + ' ' + tm(p.team) + '</h3><div class="row">' + esc(p.status) + '</div>' + (p.note ? '<div class="row">' + esc(p.note) + '</div>' : '') + srcLink(p.source) + '</div>';
    }).join('');
  }

  function moves(){
    var q = $('r4p-mq').value.trim().toLowerCase();
    $('r4p-movecards').innerHTML = db.moves.filter(function(m){
      return !q || (m.player + ' ' + m.from + ' ' + m.to + ' ' + (NAMES[m.from]||'') + ' ' + (NAMES[m.to]||'')).toLowerCase().indexOf(q) > -1;
    }).map(function(m){
      return '<div class="card"><h3>' + esc(m.player) + '</h3><div class="row">' + esc(m.from || '?') + ' <span class="arrow">\u2192</span> ' + esc(m.to) + (m.type ? ' \u00b7 ' + esc(m.type) : '') + '</div>' + (m.note ? '<div class="row">' + esc(m.note) + '</div>' : '') + srcLink(m.source) + '</div>';
    }).join('');
  }

  function sources(){
    $('r4p-srccards').innerHTML = db.sources.slice().sort(function(a,b){ return a.date < b.date ? 1 : -1; }).map(function(s){
      return '<div class="card"><h3>' + esc(s.show) + '</h3><div class="row">' + esc(s.title) + '</div><div class="row"><a href="' + esc(s.url) + '" rel="noopener" target="_blank">Watch (' + esc(s.date) + ')</a></div></div>';
    }).join('');
  }

  function show(v){
    var tabs = document.querySelectorAll('#r4p-tabs .tab');
    for (var i = 0; i < tabs.length; i++) tabs[i].classList.toggle('on', tabs[i].getAttribute('data-v') === v);
    var views = document.querySelectorAll('#r4p-app .view');
    for (var j = 0; j < views.length; j++) views[j].hidden = views[j].id !== 'v-' + v;
    try { window.scrollTo(0, 0); } catch (e) {}
  }

  var tabs = document.querySelectorAll('#r4p-tabs .tab');
  for (var k = 0; k < tabs.length; k++) tabs[k].addEventListener('click', function(){ show(this.getAttribute('data-v')); });

  $('r4p-copy').addEventListener('click', function(){
    var msg = $('r4p-msg');
    fetchFirst(AI_URLS, true).then(function(txt){
      return navigator.clipboard.writeText(txt);
    }).then(function(){
      msg.textContent = 'Copied. Paste it into any AI chat.';
    }).catch(function(){
      msg.textContent = 'Your browser blocked copying. Please try again.';
    });
  });

  fetchFirst(SOURCES, false).then(function(d){
    db = d;
    d.sources.forEach(function(s){ srcById[s.id] = s; });
    $('r4p-sub').textContent = 'Updated ' + d.updated + ' \u00b7 ' + d.players.length + ' players \u00b7 ' + d.teams.length + ' teams \u00b7 built from ' + d.sources.length + ' podcast episodes';
    teamOptions($('r4p-team')); teamOptions($('r4p-pteam'));
    quick(); teams(); players(); injuries(); moves(); sources();
    $('r4p-team').addEventListener('change', teams);
    $('r4p-pteam').addEventListener('change', players);
    $('r4p-q').addEventListener('input', players);
    $('r4p-mq').addEventListener('input', moves);
  }).catch(function(){
    $('v-quick').innerHTML = '<p class="sub">The data could not load right now. Please refresh the page in a minute.</p>';
    $('r4p-sub').textContent = 'Data unavailable';
  });
})();
//
